package com.simpletoob.app;
import org.json.*;
import java.util.*;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
/** Account collection parsing, including current lockup view models. No Android/UI dependencies. */
public final class AccountCollections {
    private AccountCollections(){}
    public static final class Channel {public final String url,name;public Channel(String u,String n){url=u;name=n;}}
    public static final class Playlist {public final String id,title;public Playlist(String i,String t){id=i;title=t;}}
    public static final class Identity {public final String name,avatar,owner;Identity(String n,String a,String o){name=n;avatar=a;owner=o;}}
    public static Identity identity(JSONObject data,String delegated)throws Exception{
        JSONObject selected=null;for(String key:new String[]{"accountItem","accountItemRenderer"})for(JSONObject j:WebJson.objects(data,key))if(j.optBoolean("isSelected")&&!j.optBoolean("isDisabled")){selected=j;break;}
        String name=YoutubeAccountProtocol.selectedName(data),avatar="",key=delegated.isEmpty()?"":"channel:"+delegated;
        if(selected!=null){avatar=thumbnail(selected.opt("accountPhoto"));String gaia=WebJson.first(selected,"obfuscatedGaiaId"),channel=WebJson.first(selected,"externalChannelId"),handle=WebJson.text(selected.opt("channelHandle"));if(handle.isEmpty())handle=WebJson.text(selected.opt("accountByline"));if(handle.startsWith("@"))handle=handle.split("[\\s·]",2)[0];if(!delegated.isEmpty())key="channel:"+delegated;else if(!gaia.isEmpty())key="gaia:"+gaia;else if(ChannelUrls.parse(channel)!=null)key="channel:"+channel;else if(handle.startsWith("@")&&handle.length()>1)key="handle:"+handle.toLowerCase(Locale.ROOT);else{for(JSONObject endpoint:WebJson.objects(selected,"browseEndpoint")){String id=endpoint.optString("browseId");if(id.matches("UC[A-Za-z0-9_-]{22}")){key="channel:"+id;break;}}}}
        if(avatar.isEmpty())for(JSONObject header:WebJson.objects(data,"activeAccountHeaderRenderer")){avatar=thumbnail(header.opt("accountPhoto"));if(!avatar.isEmpty())break;}
        String owner=key.isEmpty()?"":WebJson.hex(MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8)));
        return new Identity(name,avatar,owner);
    }
    public static boolean imageUrl(String url){try{URI u=URI.create(url);String h=u.getHost();return "https".equals(u.getScheme())&&u.getUserInfo()==null&&(u.getPort()==-1||u.getPort()==443)&&h!=null&&(h.equals("yt3.ggpht.com")||h.endsWith(".ggpht.com")||h.endsWith(".googleusercontent.com")||h.equals("googleusercontent.com")||h.equals("i.ytimg.com")||h.endsWith(".ytimg.com"));}catch(Exception e){return false;}}
    public static String thumbnail(Object raw){if(raw instanceof JSONArray){JSONArray a=(JSONArray)raw;for(int i=a.length()-1;i>=0;i--){Object x=a.opt(i);String value=x instanceof JSONObject?((JSONObject)x).optString("url"):"";if(imageUrl(value))return value;String nested=thumbnail(x);if(!nested.isEmpty())return nested;}}else if(raw instanceof JSONObject){JSONObject j=(JSONObject)raw;String url=j.optString("url");if(imageUrl(url))return url;for(String key:new String[]{"thumbnails","sources","image","thumbnail","contentImage","imageViewModel","thumbnailViewModel"}){String x=thumbnail(j.opt(key));if(!x.isEmpty())return x;}}return "";}
    public static Object content(JSONObject response){if(response.has("contents")){Object contents=response.opt("contents");for(JSONObject tab:WebJson.objects(contents,"tabRenderer"))if(tab.optBoolean("selected")&&tab.has("content"))return tab.opt("content");return contents;}if(response.has("onResponseReceivedActions"))return response.opt("onResponseReceivedActions");if(response.has("onResponseReceivedEndpoints"))return response.opt("onResponseReceivedEndpoints");if(response.has("continuationContents"))return response.opt("continuationContents");return response;}
    public static String continuation(JSONObject data){for(JSONObject j:WebJson.objects(content(data),"continuationItemRenderer")){String token=WebJson.first(j,"token");if(!token.isEmpty())return token;}for(JSONObject j:WebJson.objects(content(data),"nextContinuationData")){String token=j.optString("continuation");if(!token.isEmpty())return token;}return "";}
    public static List<Channel> channels(JSONObject data){LinkedHashMap<String,Channel> out=new LinkedHashMap<>();Object content=content(data);for(String key:new String[]{"channelRenderer","gridChannelRenderer","channelListEntryRenderer","channelListItemViewModel","channelListItemRenderer"})for(JSONObject j:WebJson.objects(content,key)){String id=j.optString("channelId");if(id.isEmpty())id=WebJson.first(j,"browseId");String url=ChannelUrls.parse(id);if(url==null){String link=WebJson.first(j,"url");if(link.startsWith("/"))link="https://www.youtube.com"+link;url=ChannelUrls.parse(link);}if(url!=null){String name=WebJson.text(j.opt("title"));if(name.isEmpty())name=WebJson.text(j.opt("channelName"));if(!out.containsKey(url)||!name.isEmpty())out.put(url,new Channel(url,name));}}return new ArrayList<>(out.values());}
    public static List<Playlist> playlists(JSONObject data){LinkedHashMap<String,Playlist> out=new LinkedHashMap<>();Object content=content(data);for(String key:new String[]{"playlistRenderer","gridPlaylistRenderer","playlistHeaderRenderer"})for(JSONObject j:WebJson.objects(content,key)){String id=playlistId(j.optString("playlistId"));if(id!=null)out.put(id,new Playlist(id,title(j.opt("title"),id)));}for(JSONObject j:WebJson.objects(content,"lockupViewModel")){String kind=j.optString("contentType"),id=playlistId(j.optString("contentId"));if(!kind.equals("LOCKUP_CONTENT_TYPE_PLAYLIST"))continue;if(id==null)for(JSONObject e:WebJson.objects(j,"browseEndpoint")){id=playlistId(e.optString("browseId"));if(id!=null)break;}if(id!=null){String name="";for(JSONObject m:WebJson.objects(j,"lockupMetadataViewModel")){name=WebJson.text(m.opt("title"));if(!name.isEmpty())break;}out.put(id,new Playlist(id,name.isEmpty()?id:name));}}return new ArrayList<>(out.values());}
    private static String title(Object value,String fallback){String text=WebJson.text(value);return text.isEmpty()?fallback:text;}
    public static String playlistId(String value){if(value==null)return null;if(value.startsWith("VL"))value=value.substring(2);return value.matches("[A-Za-z0-9_-]{2,150}")?value:null;}
    public static List<Video> videos(JSONObject data){List<Video> out=new ArrayList<>();Set<String> seen=new HashSet<>();Object content=content(data);List<JSONObject> playlistLists=WebJson.objects(content,"playlistVideoListRenderer");if(playlistLists.isEmpty())playlistLists=WebJson.objects(content,"playlistVideoListContinuation");if(!playlistLists.isEmpty())content=new JSONArray(playlistLists);for(String key:new String[]{"playlistVideoRenderer","playlistPanelVideoRenderer","videoRenderer","compactVideoRenderer","gridVideoRenderer","videoWithContextRenderer"})for(JSONObject j:WebJson.objects(content,key)){String id=j.optString("videoId");if(!VideoIds.valid(id)||!seen.add(id)||j.has("isPlayable")&&!j.optBoolean("isPlayable"))continue;String name=WebJson.text(j.opt("title")),channel=WebJson.text(j.opt("shortBylineText"));out.add(VideoMetadata.classic(new Video(id,name.isEmpty()?"YouTube video":name,channel,"",thumbnail(j.opt("thumbnail")),"","",0),j));}for(JSONObject j:WebJson.objects(content,"lockupViewModel")){if(!"LOCKUP_CONTENT_TYPE_VIDEO".equals(j.optString("contentType")))continue;String id=j.optString("contentId");if(!VideoIds.valid(id)||!seen.add(id))continue;String name="YouTube video";for(JSONObject meta:WebJson.objects(j,"lockupMetadataViewModel")){String n=WebJson.text(meta.opt("title"));if(!n.isEmpty()){name=n;break;}}JSONObject meta=j.optJSONObject("metadata");out.add(VideoMetadata.lockup(new Video(id,name,"","",thumbnail(j.opt("contentImage")),"","",0),meta==null?null:meta.optJSONObject("lockupMetadataViewModel")));}return out;}
    public static boolean explicitEmpty(JSONObject data){for(String key:new String[]{"messageRenderer","backgroundPromoRenderer"})for(JSONObject j:WebJson.objects(content(data),key)){String text=(WebJson.text(j.opt("text"))+" "+WebJson.text(j.opt("title"))+" "+WebJson.text(j.opt("bodyText"))).toLowerCase(Locale.ROOT);if(text.contains("no subscriptions")||text.contains("no playlists")||text.contains("haven't subscribed")||text.contains("haven’t subscribed")||text.contains("haven't created any playlists")||text.contains("haven’t created any playlists"))return true;}return false;}
    public static String playlistTitle(JSONObject data,String fallback){for(String key:new String[]{"playlistHeaderRenderer","playlistMetadataRenderer"})for(JSONObject j:WebJson.objects(data,key)){String title=WebJson.text(j.opt("title"));if(!title.isEmpty())return title;}return fallback;}
}
